"""Generate verifiable main-claim records from full-precision analysis outputs."""
from pathlib import Path
import argparse,json
import pandas as pd
from analysis_paths import paths
from records import ROOT

def build(root):
 root=Path(root);cp=paths(root);data=json.loads((root/'analysis/report-data/report.json').read_text());primary=data['analyses'][cp['primary_summary']];claims=[]
 def add(cid,text,evidence,expected,scope,implication,exploratory=False,experiments=(),sources=(),status='supported'):
  claims.append(dict(claim_id=cid,text=text,status=status,evidence_paths=list(evidence),source_ids=list(sources),experiment_ids=list(experiments),scope=scope,verify='Run code/reproduce.py from the submitted immutable copy as specified in VERIFY.md; compare the named regenerated tables/records at coverage0.5 with the expected full-precision values.',expected=expected,exploratory=exploratory,reader_implication=implication))
 core=['hydro_pair','hydro_decoder','pair_aef','pair_tessera'];contrasts={k:v for k,v in primary['contrasts'].items() if v['method'] in ['pair_aef','pair_tessera']}
 add('C01','Both single-distance augmentations meet the prespecified descriptive two-percentage-point improvement benchmark against both hydrological comparators in the corrected original-forest point estimates; each product has a bootstrap interval crossing zero for at least one comparator.',[cp['primary_summary']+'/metrics.csv',cp['primary_summary']+'/contrasts.csv','analysis/report-data/table-primary.md'],dict(risks={m:primary['methods'][m]['macro_risk'] for m in core},contrasts=contrasts),'Fixed12convenience windows,2024 archived products, corrected interior patches, specified random forest, label-masked NWI endpoint and nominal50%screen; no national or field-hydrology inference.','A favourable original comparison is observable, but it is not a robust cross-setting or field-validity conclusion.',experiments=['corrected-primary-rf'])
 counts=primary['counts']
 add('C02','Most evaluated nonempty query pools contain both a matching inventory regime and alternative regimes; trivial correct/wrong pools and empty pools are counted rather than hidden.',[cp['primary_summary']+'/pool-counts.csv',cp['primary_summary']+'/summary.json'],{k:counts[k] for k in ['queries','nonempty_queries','empty_queries','single_all_correct','single_all_wrong','unmatchable','nontrivial_matchable']},'Only the selected vegetation codes, polygon criteria, same-window reference roles and1km candidate buffer; pool absence is not regional absence of acceptable ecological references.','The main comparison is largely nontrivial, while pool bounds and achievable screening denominators remain necessary.',experiments=['corrected-primary-rf'])
 constant_counts=pd.read_csv(root/'analysis/constant-audit/counts.csv').astype(object);constant_counts=constant_counts.where(constant_counts.notna(),None)
 add('C03','Adding an everywhere-zero pair-feature column changes forest reference choices, confidence and screened mismatch in the archived controls, despite zero tree splits on that column; archived reference choices, best confidence and screens are unchanged for the fixed boosted-tree control.', ['analysis/constant-audit/counts.csv','analysis/constant-audit/audit.json']+[f'analysis/controls/constant-seed-{s}-summary/contrasts.csv' for s in [0,1000,2000]],constant_counts.to_dict('records'),'Initial-extraction original cohort; three forest seeds at max_features0.7, one at1.0, and one fixed boosted-tree learner. This is a measured counterexample for these fits, not a universal property or a unique causal account of tree construction.','An improvement after adding a feature can reflect the changed fitted pipeline even when the new feature contains no varying site information.',True,['constant-controls','post-correction-control-summaries'],status='supported')
 corrected_constant=root/'analysis/constant-corrected-audit/counts.csv'
 if corrected_constant.exists():
  repeated=pd.read_csv(corrected_constant).astype(object);repeated=repeated.where(repeated.notna(),None)
  claims[-1]['expected']={'initial_extraction':claims[-1]['expected'],'corrected_path_replay':repeated.to_dict('records')}
  claims[-1]['evidence_paths']+=['analysis/constant-corrected-audit/counts.csv','analysis/constant-corrected-audit/audit.json']
  claims[-1]['experiment_ids'].append('corrected-constant-replay')
  claims[-1]['scope']+=' The seed-offset0 physical conditions were author-refitted on canonical corrected paths; physical arrays are unchanged, so these are expected replay checks and not additional independent observations.'
 sensitivity={}
 for key in ['analysis/controls/seed-1000-summary','analysis/controls/seed-2000-summary',cp['hgb_summary'],cp['recent_summary']]:
  a=data['analyses'][key];sensitivity[key]={k:v for k,v in a['contrasts'].items() if v['method'] in ['pair_aef','pair_tessera']}
 add('C04','The original raw-cosine-distance gains are not consistently maintained against both hydrological comparators across the specified forest seeds, the fixed boosted-tree learner and the exploratory recent-image panel.',list(sensitivity)+['analysis/report-data/contrasts-all.csv'],sensitivity,'Specified diagnostic settings and18convenience windows across two panels; seed controls use initial extraction and are internally paired. Recent landscapes/training sizes differ, so this does not identify an effect of inventory age.','The study does not establish a stable raw-cosine-distance increment; it also does not establish absence of useful information in the full representations.',True,['corrected-learner-reader-recent','control-seed-1000','control-seed-2000'])
 add('C05','Own-screen gains combine differences in reference ranking and differences in which queries are retained; evaluating the same hydrological query screen changes the estimated increment.', ['analysis/report-data/screen-decomposition.csv',cp['primary_summary']+'/fixed-screen-risk.csv'],data['screen_decomposition'],'Corrected original forest at nominal50%coverage; exact algebraic decomposition using archived selected sets. Not a causal mediation analysis.','Compare reference quality on common queries as well as at an equal screening budget.',False,['corrected-primary-rf'])
 noise={}
 for setting in ['noise','noise-all']:
  for i in range(3):
   key=f'analysis/controls/{setting}-{i}-summary';noise[key]=data['analyses'][key]['contrasts']['pair_noise|hydro_pair']
 add('C06','Outcome-independent scalar controls sometimes yield original-setting point improvements comparable to the satellite distances; their all-feature forest differences are smaller in the three archived repetitions.',list(noise)+['analysis/report-data/contrasts-all.csv'],noise,'Three deterministic hash-scalar repetitions, same archived primary pools/labels, specified forests. No permutation p-value or general estimate of all random scalars.','A scalar augmentation control helps assess whether a gain is attributable to the measurement.',True,['strict-noise-remaining'])
 poly=json.loads((root/cp['polygon_features']/'derivation-record.json').read_text());add('C07','The dispersed-polygon measurement comparison uses a single quality- and context-filtered cohort; all shared formerly valid raw pixels agree after the tile-edge repair.',[cp['polygon_features']+'/derivation-record.json',cp['polygon_features']+'/exclusions.json','analysis/tile-edge-audit/feature-correction-check.json','data/corrections/edge-correction-manifest.json'],dict(original_n=poly['original_n'],common_n=poly['common_n'],excluded_n=poly['excluded_n'],all_region_overlap_checks_equal=all(r['raw_values_on_overlap_exactly_equal'] for r in poly['audits'])),'Outcome-blind fixed quality/context rules and sampled pixels; does not validate field hydrology, all polygon pixels or physical-neighbourhood independence.','Differences between completed polygon conditions can be assessed without a changing site cohort; measurement errors remain visible.',True,['polygon-feature-derivation','polygon-feature-derivation-v2','polygon-feature-derivation-v3','tile-edge-correction'])
 if all(f'analysis/polygon/C-{learner}-summary' in data['analyses'] for learner in ['rf','hgb']):
  expected={}
  cases=[]
  for learner in ['rf','hgb']:
   expected[learner]={}
   for condition in ['B','C']:
    key=f'analysis/polygon/{condition}-{learner}-summary';cases.append(key);a=data['analyses'][key];expected[learner][condition]={m:a['methods'][m]['macro_risk'] for m in ['hydro_pair','hydro_decoder']}
   b=expected[learner]['B'];c=expected[learner]['C'];assert (b['hydro_pair']-b['hydro_decoder'])*(c['hydro_pair']-c['hydro_decoder'])<0
  if data.get('input_change_audit'):expected['input_change_audit']={k:data['input_change_audit'][k] for k in ['physical','embedding']}
  add('C08','Holding the dispersed embedding vectors and common cohort fixed, averaging existing physical feature maps at those locations changed which physical comparator had lower mismatch in each of the two original learner settings.', [key+'/metrics.csv' for key in cases]+['analysis/polygon-condition-audit/result.json','analysis/input-change-audit/result.json','analysis/input-change-audit/physical-summary.csv','analysis/input-change-audit/embedding-summary.csv'],expected,'Exploratory3624wetland common cohort,2024 products, primary forest fraction0.7 and fixed boosted trees. This is a fitted-pipeline measurement-operator comparison; it does not validate field hydrology, identify a unique mechanism, or imply improvement for every learner.','Include both physical pair/category comparators and test their spatial measurement operators; baseline choice can change the apparent satellite increment.',True,['polygon-AB-comparisons','polygon-C-comparisons','input-change-audit'])
 white_key='analysis/metric-whitened/primary-hgb-summary'
 if white_key in data['analyses']:
  a=data['analyses'][white_key]
  expected=dict(risks={m:a['methods'][m]['macro_risk'] for m in core},contrasts={k:v for k,v in a['contrasts'].items() if v['method'] in ['pair_aef','pair_tessera']})
  if 'analysis/controls/all-corrected-seed-0-summary' in data['analyses']:expected['all_feature_physical_pair_forest']=data['analyses']['analysis/controls/all-corrected-seed-0-summary']['methods']['hydro_pair']['macro_risk']
  add('C09','In the exploratory original-panel boosted-tree comparison, both training-only whitened distances yield point improvements of at least two percentage points against both physical comparators; each product has an interval crossing zero against at least one comparator.',[white_key+'/metrics.csv',white_key+'/contrasts.csv','analysis/whitening-svd-audit/result.json','analysis/controls/all-corrected-seed-0-summary/metrics.csv'],expected,'Corrected original3667wetlands,2024 products, unchanged1% covariance-eigenvalue floor, fixed boosted-tree learner and original50%screen. These are within-learner comparators; the all-feature physical forest has lower point mismatch than these boosted-tree augmentations. Operator chosen after the planned metric diagnostic; no independent confirmation or field validation.','Metric choice can recover favourable conditional point estimates; this does not establish superiority over every tested physical method or justify rejecting all satellite-distance measurements.',True,['whitened-distance-hgb'])
 pool=data.get('pool_diagnostic',{})
 if pool:
  expected=dict(conditional=[r for r in pool['conditional'] if r['analysis'] in [cp['primary_summary'],white_key] and r['method'] in ['pair_aef','pair_tessera']],influence=[r for r in pool['influence'] if r['analysis']==cp['primary_summary'] and r['baseline']=='hydro_pair' and r['method'] in ['pair_aef','pair_tessera']])
  add('C10','Shared-query nontrivial-pool diagnostics and all-window omission checks qualify the original own-screen gains; the AlphaEarth point benchmark against the pair baseline is sensitive to one window omission.',[pool['path']+'/fixed-nontrivial.csv',pool['path']+'/leave-window-out.csv','analysis/report-data/window-influence-overview.csv'],expected,'Exploratory retrospective diagnosis of archived half-coverage screens. Labels condition already-selected queries, without replacement. No causal decomposition, revised primary population, national estimate or independent replication.','Report equal-budget screening and same-query reference quality separately, with window and conditional-query denominators.',True,['pool-window-diagnostic-v1','pool-window-diagnostic-v2','pool-window-diagnostic-v3'])
 budget=data.get('budget_diagnostic',{})
 if budget:
  comparisons=[]
  for row in budget['contrasts']:
   if row['coverage']!=.5:continue
   original=data['analyses'][row['analysis']]['contrasts'][row['method']+'|'+row['baseline']]
   comparisons.append(dict(**row,original_difference=original['difference'],benchmark_changed=bool((row['difference']<=-.02)!=(original['difference']<=-.02))))
  assert any(r['benchmark_changed'] for r in comparisons)
  add('C11','Changing the allocation of a nominal half-coverage screening budget changes whether the descriptive two-point benchmark is met for some tested augmentation contrasts.',[budget['path']+'/metrics.csv',budget['path']+'/contrasts.csv',budget['path']+'/selected-050.csv'],comparisons,'Eight fixed corrected input/learner conditions and two post-primary observable-stratum policies. Window-total allocation changes rounding totals; vegetation allocation preserves original per-rotation totals. No withheld regime label selects queries, and no revised primary result, normative fairness or ecological-benefit claim is made.','Specify the acceptance policy and realized denominators before interpreting an incremental screening benchmark.',True,['budget-allocation-v1'])
 if all(f'analysis/year-{year}-summary' in data['analyses'] for year in [2023,2021]):
  annual={2024:primary,**{year:data['analyses'][f'analysis/year-{year}-summary'] for year in [2023,2021]}}
  expected={str(year):{m:a['methods'][m]['macro_risk'] for m in core+['aef_cosine','aef_whitened','tessera_cosine','tessera_whitened']} for year,a in annual.items()}
  assert expected['2021']['pair_aef']<expected['2024']['pair_aef']
  add('C12','On the identical annual common cohort, the2021 raw AlphaEarth pair augmentation has lower point mismatch than its2024 counterpart while physical-only decisions remain unchanged.', ['analysis/year-common/manifest.json','analysis/year-condition-audit/result.json','analysis/year-2021-summary/metrics.csv','analysis/year-2023-summary/metrics.csv',cp['primary_summary']+'/metrics.csv'],expected,'Same3667wetlands, fixed inventory labels and baseline physical maps, three archived embedding years, original forest/seeds and nominal50%screen. No temporal field validation, causal landscape-change effect, forecasting result or general optimal-year claim.','Report the embedding year when evaluating historical inventory agreement; a favourable inventory match does not identify the year or method that best represents current field hydrology.',True,['year-2023-matching','year-2021-matching','annual-physical-invariance'])
 strong_keys=[f'analysis/transfer-strong/{condition}-summary' for condition in ['rf-all-benchmark','hgb-raw','hgb-white']]
 if all(key in data['analyses'] for key in strong_keys) and (root/'analysis/strong-transfer-audit/result.json').exists():
  expected={key:dict(risks={m:data['analyses'][key]['methods'][m]['macro_risk'] for m in core},contrasts={k:v for k,v in data['analyses'][key]['contrasts'].items() if v['method'] in ['pair_aef','pair_tessera']}) for key in strong_keys}
  raw=expected['analysis/transfer-strong/hgb-raw-summary']['contrasts']
  assert all(raw['pair_tessera|'+base]['difference']<=-.02 and raw['pair_tessera|'+base]['low']<0<raw['pair_tessera|'+base]['high'] for base in ['hydro_pair','hydro_decoder'])
  add('C13','In the exploratory other-window-training boosted-tree comparison, raw TESSERA distance yields a point improvement of at least two percentage points against both physical comparators; both paired window-bootstrap intervals cross zero.',[key+'/metrics.csv' for key in strong_keys]+[key+'/contrasts.csv' for key in strong_keys]+['analysis/strong-transfer-audit/result.json'],expected,'Fixed twelve target windows, original transfer training pairs and query/reference roles, corrected2024 features, fixed boosted trees and nominal50%screen. Added after inspection of the original transfer results. Training geography, size, seeds and indicators differ from the primary experiment; no causal label-availability effect, validated model selection, independent confirmation or field validation.','Favourable raw-distance comparisons persist in a different training setting even with stronger comparators; the preferable metric and learner cannot be generalized from one fitted setting.',True,['strong-transfer-1','strong-transfer-2','strong-transfer-3','strong-transfer-4','strong-transfer-summary'])
 from review_claims import revise
 revise(claims,data,root)
 for row in claims:
  # All expected floats are serialized from analysis outputs; JSON contains no NaN.
  assert row['evidence_paths'] and row['scope']
 (root/'claims.jsonl').write_text(''.join(json.dumps(v,allow_nan=False)+'\n' for v in claims));print(json.dumps(dict(claims=len(claims),supported=sum(v['status']=='supported' for v in claims))))

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,default=ROOT);a=p.parse_args();build(a.root)
